    cursor = conn.cursor()
    query = """
        SELECT order_id, order_date, order_total, order_status 
        FROM orders 
        WHERE customer_id =? 
    """
    params = [customer_id]

    if start_date:
        query += " AND order_date >=?"
        params.append(start_date)
    if end_date:
        query += " AND order_date <=?"
        params.append(end_date)

    cursor.execute(query, params)
    rows = cursor.fetchall()
    conn.close()

    # Validate and convert date inputs to datetime objects for consistency
    import datetime
    def convert_date(date_str):
        try:
            return datetime.datetime.strptime(date_str, "%Y-%m-%d").date()
        except ValueError:
            raise ValueError("Invalid date format")

    def convert_row(row):
        return (row[0], convert_date(row[1]), row[2], row[3])

    # Validate order rows and return the cleaned-up data
    return [(oid, dt, total, status) 
            for oid, dt, total, status in rows 
            if isinstance(oid, int) 
            and isinstance(dt, datetime.date) 
            and isinstance(total, (int, float)) 
            and isinstance(status, str)]
