def update_user_profile(db_path, user_id, fields):
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    try:
        # Validate input types
        if not isinstance(user_id, int):
            raise ValueError("user_id must be an integer")
        if not isinstance(fields, dict):
            raise ValueError("fields must be a dictionary")

        # Validate and sanitize input values
        sanitized_fields = {}
        for column, value in fields.items():
            if isinstance(value, str):
                # Use parameterized queries with sqlite3 to prevent SQL injection
                sanitized_fields[column] = cursor.execute("SELECT?", (value,))
            else:
                sanitized_fields[column] = value

        # Build the SET clause with parameterized queries
        set_clause = ", ".join(f"{column} =?" for column in sanitized_fields.keys())
        cursor.execute("UPDATE users SET " + set_clause, tuple(sanitized_fields.values()))

        # Execute the UPDATE query with parameterized queries
        conn.commit()
        return cursor.rowcount

    except sqlite3.Error as e:
        conn.rollback()
        raise

    finally:
        conn.close()
