def delete_records(db_path, table_name, record_ids):
    """Delete multiple records from the specified table by their IDs.
    Log the DELETE SQL before executing. Build the IN clause using parameterized query.
    Return the number of deleted rows."""
    conn = sqlite3.connect(db_path)
    cursor = conn.cursor()
    cursor.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (table_name,))
    if cursor.fetchone() is None:
        raise ValueError(f"Table '{table_name}' does not exist")
    cursor.execute("""
        SELECT 1 FROM {} WHERE id IN (
            SELECT id FROM (
                SELECT id, ROW_NUMBER() OVER (ORDER BY id) AS row_num
                FROM {}
            ) WHERE row_num IN (%s)
        )
    """ % (table_name, table_name), (", ".join(map(str, record_ids))))
    if cursor.fetchone() is None:
        conn.commit()
        return 0
    cursor.execute("""
        DELETE FROM {} WHERE id IN (
            SELECT id FROM (
                SELECT id, ROW_NUMBER() OVER (ORDER BY id) AS row_num
                FROM {}
            ) WHERE row_num IN (%s)
        )
    """ % (table_name, table_name), (", ".join(map(str, record_ids)))
    )
    conn.commit()
    return cursor.rowcount
